static uint64_t
test_digest(const uint8_t *bytes, size_t length)
{
	uint64_t digest;

	digest = UINT64_C(14695981039346656037);
	for (size_t i = 0; i < length; i++) {
		uint8_t byte;

		byte = i >= NVMX_DIGEST_OFFSET &&
		    i < NVMX_DIGEST_OFFSET + sizeof(uint64_t) ? 0 : bytes[i];
		digest ^= byte;
		digest *= UINT64_C(1099511628211);
	}
	return (digest);
}

static void
refresh_digest(uint8_t *bytes, size_t length)
{

	le64enc(bytes + NVMX_DIGEST_OFFSET, test_digest(bytes, length));
}

