	memset(&fixture, 0, sizeof(fixture));
	fixture.expected = id;
	fixture.expected_indicator = 4;
	fixture.error = EIO;
	memset(&request, 0xa5, sizeof(request));
	before = request;
	ATF_CHECK_EQ(vmx_nested_context_abort_published_vmexit(&context,
	    false, 4, &ops, &fixture, &request), EINVAL);
	ATF_CHECK_EQ(vmx_nested_context_abort_published_vmexit(&context,
	    true, 0, &ops, &fixture, &request), EINVAL);
	ATF_CHECK_EQ(fixture.calls, 0);
	ATF_CHECK_EQ(memcmp(&request, &before, sizeof(request)), 0);
