static int
test_vmexit_handoff_boundary_commit(void *arg,
    const struct vmx_nested_vmexit_handoff_request *request)
{
	struct handoff_callback_boundary_fixture *fixture;

	fixture = arg;
	fixture->calls++;
	if (request == NULL)
		return (EINVAL);
	if (fixture->mutate) {
		((struct vmx_nested_vmexit_handoff *)fixture->handoff)->state =
		    VMX_NESTED_VMEXIT_HANDOFF_IDLE;
		((struct vmx_nested_vmexit_handoff *)fixture->handoff)->
		    request.information.exit_reason = UINT32_MAX;
	}
	return (0);
}

